) AS (
  VALUES 
    (398::BIGINT, 'Excelente profesor, perfectamente TOP 3 de la escuela. Quizás si califica algo duro, pero es acorde a como enseña. Si está dispuesto a aprender (a esforzarse) muy recomendado.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '5eb93a82bbb21471cf39cfc5cb8aa02b77c5def33926388c389248c03dac19bf'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Todos los comentarios malos de el están esperando revisión, por qué será? Los proyectos de este laboratorio son increíblemente largos, no tiene sentido. Prepárese si lo lleva con él para trabajar porque este laboratorio es como si fuera un curso de 3 créditos en lugar de 1'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, '5e0d0680433d34c13adbab7225d9650d18c0b85d4f9c107720dfafb0ecd9f8e5'::TEXT, ARRAY[1277]::BIGINT[]),
    (398::BIGINT, 'De los mejores profes de electro, explica DEMASIADO bien, eso si que sea bueno no significa que sea fácil, si usted le pone al curso el te ayuda infinitamente con sus clases que son muy provechosas y con sus videos de YT, si no le pone al curso 100% muere.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'ad45e84d51f6cbff5aa6a94749b43732916d34906dca26a4df171a17935da1d7'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Evitenlo a todas costas'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2026-02-23T00:00:00+00:00'::TIMESTAMPTZ, 'c2c58814ca04e261aad15b7b49b0f8317037cd9f58009a8eb2605187661707df'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'De no ser porque califica en binario, sería el mejor profesor hasta el momento, eso más que el curso es super pesado debido su rúbrica de 100% exámenes. Sus ideas son claras y realiza bastantes ejercicios antes del examen, pero aún así no es suficiente para la complejidad de sus exámenes'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, '31f3b85f389305e106a2563c118a44bd0014e1212c6d625c3c27b4996ccf9724'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'El profe no revisa nada hasta final de semestre entonces se siente algo desorganizado todo. En la clase casi nunca está y con el proyecto es un poco necio en buscar errores que muchas veces no existen.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '0db56e636f83785537222147b218d3711458f5e3d07bf628f1359ca42b57a91e'::TEXT, ARRAY[1277]::BIGINT[]),
    (398::BIGINT, 'Muy buen profe, si matricula con él sepa que estudiando un día antes del examen no va a ser suficiente, califica duro'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'cf35ff096ac48ccb9d1c98d99082c2c93c680baed17b908ba477707ed556e3cf'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Probablemente el curso más pesado de la carrera, sin embargo el profe se esfuerza por hacer las clases bastante provechosas y explica muy bien la materia. Al final va a tener que estudiar y practicar DEMASIADO por su cuenta si quiere pasar SyS. Recomiendo ver los videos de Youtube de Barboza.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'd1a4375f869bb34a38a54680e272a9e2d9bb1f58e63e5a3cc27a10acf8bfee68'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Se interesa porque aprenda y esta dispuesto a ayudar pero si califica duro'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2024-06-26T00:00:00+00:00'::TIMESTAMPTZ, '8f924057bf3dfa210acb4b670c3a1d13a90123504b081f9c699d9f691eaccff8'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Es un excelente profesor, explica muy bien y se nota que de verdad le importa que los estudiantes aprendan, pero califica muy duro.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Clases excelentes']::TEXT[], '2024-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'd5c7ace6231c00a82407083566599b21a7b240f2b2774cb4cf6ac216e2ff2110'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Lo odias por lo dificil de sus cursos pero al finalizar lo amas jajaj'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases largas']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'a3c39169049eb94e6bb20638feafade7c9ea8654ba36b17d09081eb23b889877'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'De los mejores profesores de electrónica. Clases son asi 30 min de teoria y luego hace la mayor cantidad de ejercicios hasta que termine la clase. Siempre dispuesto a clarar dudas, y es muy buena gente. Creo que intenta enseñar todo lo posible para el examen. Sys duro, pero con este profe se suavisa'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-02-02T00:00:00+00:00'::TIMESTAMPTZ, '29cc43d66709f3f60a54aa28bc938491e1a39b60877020b4e68353f38fddae44'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'El profesor Barboza se esfuerza por dejar la materia lo más clara posible, es muy apasionado a la hora de enseñar y eso se agradece. Califica justo, no le va a robar medio punto pero tampoco se lo va a regalar. En general, es un buen profesor para llevar el curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'e350bcd5c4b19beb7cbe628ebd86a9716952048acc7b8f0f2cb404883b5f66b4'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'El lab como cualquier otro es pesado y consume bastante tiempo sin embargo se aprende demasiado y los proyectos son interesantes. El proyecto final es muy divertido. Ademas se aprenden a usar herramientas que se utilizan en otros cursos como Git y Latex'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2023-01-22T00:00:00+00:00'::TIMESTAMPTZ, '4b82d7ac3eea0ab60ce7da22ab42cab2885099ea94f12a39918aed813bfbd3d3'::TEXT, ARRAY[1277]::BIGINT[]),
    (398::BIGINT, 'Excelente profesor, pero el curso se ve perjudicado por la dura rúbrica que tiene y el montón de contenido difícil que lo abarca, los exámenes tienen curva pero si no se estudia bastante, no se pasa.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2022-12-17T00:00:00+00:00'::TIMESTAMPTZ, '0d69240238f10b1cee6fdf32e7b8b1d6d3ddbf4f686be5d699c6ad035814b8ac'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'El curso como tal es pesado pero llevarlo con Barboza vale completamente la pena. Tiene el curso muy bien estructurado y se aprende bastante! Lo único que deben tomar en cuenta es que con él se gasta mucha plata en componentes'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2022-12-10T00:00:00+00:00'::TIMESTAMPTZ, '1af13f7488d3cd813c5dacafaee1d830224dbea1261b1e361ea16f73ae17c78a'::TEXT, ARRAY[1277]::BIGINT[]),
    (398::BIGINT, 'Buen profesor pero el sistema de calificación binario que utiliza perjudica al estudiando y solo lo beneficia a él, acortando el tiempo de revisión. De ser posible matriculen con William y ven los vídeos de Barboza, todo lo tiene en YouTube'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ac4f38603f46032cdbe9905dedcc2ffe093b7ab6b646a6ad8d2ed0d98574b35c'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'El lab en sí con él es pesado porque quita bastante tiempo, pero no es nada imposible, todo está respaldado en la lectura. Recomiendo llevarlo con el porque se aprende demasiado pero también tiene que trabajar duro por ello. El profe es pura vida y ayuda bastante si usted tiene deficiencias'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'a04c017bbbb92fbf911f7415d47cebde14c0ac5185b2d38163f4d421b27d7a8f'::TEXT, ARRAY[1277]::BIGINT[]),
    (398::BIGINT, 'El curso por sí solo es pesado y difícil, independientemente del profe. Tiene bastante bien organizado el curso aunque a veces son demasiados videos para ver en la semana. Es bueno llevar la materia adelantada para llegar bien a la clase. Hace muchos ejercicios y me parece una muy buena opción.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '9b8cd6e112631ee9cce9dac41e3b5712435dbb5b526832ff4abb4e9f6906e9ca'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'El curso es muy bonito, se aprende bastante. Hay que bretear mucho pero lo vale, e igualmente el curso se pasa con solo entregar todos los trabajos. El profesor es buena nota y en general, lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '3f906ecf791785e39dd68380877115039d0166c225ae39929fc0ca36d7a4dc85'::TEXT, ARRAY[1277]::BIGINT[]),
    (398::BIGINT, 'La verdad el profe se esfuerza porque uno entienda. El problema es que ese esfuerzo de él, implica el triple de esfuerzo de uno, porque deja hasta 4 clases para ver por semana, de 2 horas y media cada una. Califica súper binario e injusto porque cree que todo está perfecto o completamente malo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2022-05-23T00:00:00+00:00'::TIMESTAMPTZ, '84b54850effd55fbbe0259f7781211838c06d5ce5c10676477a8e6c0f9e928d7'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Los contenidos del curso no son difíciles, pero el profesor deja tareas que implican mucha investigación, se necesita destinar bastante tiempo al curso, deja clases grabadas de otros semestre para ver la materia, en clase resuelve ejercicios del libro.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'ddd0eb2130a53c1d507d0342a3a731d0a7879007ed439daecc1b9de88b30eaaf'::TEXT, ARRAY[1288, 1289, 1373]::BIGINT[]),
    (398::BIGINT, 'Da mucha materia y mucho material para la clase, se ve la materia en videos y hay una clase sincronica a la semana para realizar solamente ejercicios, deja una tarea por semana. Si lleva las tareas y la materia al dia hace el curso mas llevadero.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'b1040128db57db5e81997f965b42e535338bc69fc701ad9acd20b9140e8d45e2'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'La cantidad de tiempo que invertí para pasar Señales es un chiste a la par de la cantidad de tiempo que le dediqué a este lab. El profe deja labs larguísimos y el trabajo es individual. El proyecto es pesado pero muy chiva. Es un curso donde se suda sangre pero se goza. La verdad aprendí demasiado.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2021-08-19T00:00:00+00:00'::TIMESTAMPTZ, '962a6535b8561a7347d0cd7e306473f190c23364bb9931c383197b1480c81f03'::TEXT, ARRAY[1277]::BIGINT[]),
    (398::BIGINT, 'Buen profesor. En virtualidad, la mitad de la clase es para ver la materia que ya tiene grabada y la otra realiza ejercicios en vivo. Se hace más llevadera la clase. Los ejercicios sirven para el examen. Deja lecturas cada semana, recomiendo llevarlas al día para entender los ejercicios de clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '115354d6347bfa34f570567552069ea09a657c32067b7ad5ad51a37ef7778f5f'::TEXT, ARRAY[1288]::BIGINT[]),
    (398::BIGINT, 'El curso con el profe es super pesado, pero él es muy ordenado para realizar los laboratorios, divide el grupo en dos, uno presencial y otro con material parecido al laboratorio para la casa, el profe es buena gente. Curso largo y pesado, pero bonito con él.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'cab9206a7d18b060bccec5ce5de625aff9af5a51afbfb0a16467aa7cda6e7c7d'::TEXT, ARRAY[1277]::BIGINT[]),
    (398::BIGINT, 'Barboza hace que lab valga al menos 3 créditos. Dividió al grupo en 2, uno presencial y otro desde la casa con ELVIS. Laboratorios larguísimos, todo individual, devolvió notas hasta final de semestre. Si matricula con él prepárese a no tener tiempo de nada.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '3a4465161b3a7e513353b5479542b65d21c18450aa0069d6b474753ef97e51c4'::TEXT, ARRAY[1277]::BIGINT[]),
    (398::BIGINT, 'Es un buen profe y siempre está dispuesto a ayudar, sin embargo deja muchos videos para ver durante la semana.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '90a861dd13b10966fe3f61f0048a22c679b4dc2917cb6a162be63055ffde7101'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'La forma de dar el curso virtual es muy buena,, bastante práctica y explica super bien, da mucho material extra para entender mejor, las cosas malas del curso son por la forma de evaluar el curso que por el profe'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-16T00:00:00+00:00'::TIMESTAMPTZ, '674995a9d3b1f20d0e2a6a57f4b9b25c76f259b42dcfc57e90adbdaf15021c2b'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'El mae es uno de los profesores más apasionados en la enseñanza del curso, brinda mucho material para que usted estudie y entienda los temas, pero él no le regala nada. Depende de usted poner de su parte para poder pasar el curso de manera correcta, super recomendado.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2021-03-12T00:00:00+00:00'::TIMESTAMPTZ, '259400f80aca66376e34221e744765217b2b6ccf03150adf9911d3db524398d0'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Cualquier curso que el profesor explique es bueno. Ayuda al estudiante, lo respeta y, se preocupa para que el estudiante supere los cursos. Súper recomiendo para cualquier curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '0617b938e819831e27fc7da6d95bf47dfade521345d0cdcadccee4ba2d0c9289'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'El es buenísimo dando la materia, la maneja muy bien, pero este semestre casi que nos puso a ver videos del semestre pasado. El me parece una persona apática y que no ayuda. NO METAN TUTORÍAS, a menos que quieran un 6% con curva en quices. Exámenes del GAAP larguísimos y duros.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '0eb670571d9c0af2e247c45dd97d57c32cac3262dfd97c20d3fb636401aa5a82'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Las consignas semanales son ver 2 o 3 videos de 2h minimo del semestre anterior, no da puntos por procedimiento, en clase se entiende todo claro y los parciales es otro viaje diferente. Los quices (tuto) mas bien perjudican.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '83311eff6feb921612828ed0f7f3a7550c7d1bd57f36603cef08f04284a5315b'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'El curso es duro , hay que ponerle . El profe es muy bueno explicando pero casi todo el semestre nos mandaba videos de clases de semestre anterior y habia que tenerlos vistos para el viernes , eran 2 videos min de 2 h minimo . Califica justo y el formato de las tutos mas bien perjudica.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '51d62a26fa33b3ccbda748c43b00c182ccc14bbcba766b3261b6e47550c03cf1'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Explica muy bien, a veces se enreda pero se corrige rápido, siempre atento a responder dudas ya sea en horas de consulta o por correo, califica justo y general, es buen profesor para llevar el curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '675352f2eae2a53cfcc3d7d6f8b67d7fb76aaca9be06fd2420d80016cf4f4dbb'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'De los mejores de electro. Muy pesado el curso, se debe seguir las recomendaciones que hace y ponerle a las sesiones de ejercicios que hace antes de examen'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '0b9f862560a260316743637f93be6ed6ea268a6c7e1867d9d6f6b030c05cdf4f'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'El curso ya por si sólo es duro, sin embargo explica bastante bien y trata de hacerlo hasta que uno entienda. No califica tan duro como dicen, de hecho no busca joderlos a uno. Me parece buen profesor para llevar el curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-06T00:00:00+00:00'::TIMESTAMPTZ, '9e4ac9e4b3ef5fa719ec1d66a636c4484cab6ee6d270dc559c84f32e3d504f08'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Excelente profe, se toma todo el tiempo necesario para explicarle, de lo mejor en electro. Más de una vez, dedicó horas extra para atender consulta. Antes del examen final, hace exámenes él mismo, muy útil. El mae todo buena gente. Hay que hacer muchos ejercicios y aprovechar las consultas. Recomend'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'a26a0d500f7a912de080d66a69fe457f12a63b6d7cbbca38437979d825ebc7c2'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Enfoca mas la clase en aspectos prácticos que teóricos. Buen profesor para el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-01-29T00:00:00+00:00'::TIMESTAMPTZ, '6e22cc5e8a5f350a4d1f2b2982610ccb022eed416717abdc6c9ec0cf295dcc1c'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '45d3df8394ead04ec4905e757f38a16da80addd81b44506e1aa89cf1d5609bad'::TEXT, ARRAY[3057]::BIGINT[]),
    (398::BIGINT, 'Las clases no ayudan tanto como otros dicen'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'f605df7b03462bc3f05c739bff8ea562ad0c491b3e67371fd96151b08db883b4'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'La verdad no llevé muchas clases con él, lo que sí sé es la calidad de persona que es. Es una persona que aprecia la sinceridad y el esfuerzo del estudiante.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-09-26T00:00:00+00:00'::TIMESTAMPTZ, '31b6e75c76ac19a3144d738e7ba51bc502117969eef977776b74429e3a9d8dcc'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Explica muy bien, hay que estudiar para los exemanes, apenas da el proyecto se debe iniciar porque es usualmente largo, falta un poco mas de practica en el curso.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2019-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'a94ed539244b312b265117ce70cc516f9d70be52cc0145ceafa5038b260f936c'::TEXT, ARRAY[1339]::BIGINT[]),
    (398::BIGINT, 'Súper binario, increiblemente. Revisa que le dé el resultado, nada más, es un profe para aprender y luego pasar el curso con otro profe.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '6bdc773ea44df3de1403947d19557639412e67f0dfc7acfa280266b8d87f725d'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'El curso deporsí ya es pesado, pero Barboza es un dios explicando. Lo feo es que califica muy rudo pero por lo general ayuda bastante.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd6a337fc0213ff88f27b9757c13adfd4bd3836c3ecb73d10bbe77340b4c81476'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Las clases SIEMPRE son a las 7:30, puede que no pase lista, pero es mucho jugarle al vergas. (Asistencia obligatoria). Llorarle puntos no sirve de nada, explica súper bien, atiende consulta y en general es buena persona aunque a veces se le sube el ego a la cabeza por puras tonteras'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'e01178b99bd3a499798193f015d9aab78a1d4e47534a9043a256fd59fac0971e'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Es excelente explicando, brinda mucho material de apoyo y siempre está anuente a las dudas. La única desventaja es que no siempre se puede aprovechar todo lo que ofrece por el tiempo. A como es de buen profe así de duro evalúa. Es casi binario pero si se estudia bastante las curvas compensan.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'ca365948c366653761354ce14f4835c7aa2836ab0caa26b885a299c2ab6357f0'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2019-03-10T00:00:00+00:00'::TIMESTAMPTZ, '01390e163aba8a9b9204ca263ca9b419d92ea5de2abf3b5080473654acd5b76e'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Excelente para dar el curso, en clase dura mucho explicando y se atrasa pero el explica hasta que uno entienda y lo relaciona mucho con la carrera. Hay que practicar mucho tanto en verano como semestre para no equivocarse tanto.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'c9e6780abea1246e6a4613a1e80bb7af183fcabcdb5dae17291aa7c9e8bbc7ea'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Excelente profe , hay que practicar bastante porque se pueden cometer muchos errores en los exámenes Y en eso baja muchos puntos, pero las explicaciones en clase y práctica son demasiado útiles'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'f493ad62229a10928cf76239b8cbc8460a5af1e43807d1dd81f0f4b02bb2fe86'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'El curso en sí es difícil. Explica excelente y hace muchos ejercicios en clase, lo prepara bien a uno para otros cursos. Califica justo a pesar de que muchos dicen que es binario, si usted es de los que no le gusta trabajar duro este profe no es para usted. Super recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-25T00:00:00+00:00'::TIMESTAMPTZ, 'e4651d339e876da33510da15c226b4a1179a32b8e83b5ff01cde667cfb6c5d03'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Él sabe todo lo que hay que saber en el campo y se nota en la clase. Hace todos lo ejercicios que sean necesarios. Con frecuencia hace quices bien difíciles de pasar por lo que son la forma perfecta de estudiar para el examen final. El profe no es difícil pero solo le gusta dar cursos difíciles.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos exámenes', 'Clases excelentes']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, '932d36f5c6d69db390310b996f6ad2c681098fea9a69d405d009b13feb61e96d'::TEXT, ARRAY[1339]::BIGINT[]),
    (398::BIGINT, 'El profe le pone mucho amor al curso. Es de los mejores de la Escuela de electrónica. Cada semestre él adquiere más experiencia que a su vez aplica en el siguiente semestre. Además califica normal y la curva que hace ayuda mucho. Super recomendado. No dude en matricular con él.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-01T00:00:00+00:00'::TIMESTAMPTZ, '51403486d823e5c103924f7634138854d80e9cbaad44eaac6d1b9f34bc32e154'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Explica excelente, las clases son de 25% teoría y 75% ejercicios, así uno aprende la teoría a pura práctica. Eso si, califica si está bueno o malo, listo. Excelente profesor. Recomiendo meter tutorías ese 10% en la nota fina es mágico jajaja.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '46a13c64c32c37e790f651660176197fed67d9c5182ce803479ed367565a51e9'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Es excelente como profesor, muy ordenado. Explica muy bien. El único problema es que sus calificaciones son completamente binarias: se tiene todo el problema correcto o se tiene cero.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'e14801d96d790c4e12725e757c9d84578ba6eeccd200ad4ca3a8ecb9a9e7ac48'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Muy buen profe. Domina muy bien la materia y en consulta ayuda demasiado. El mae se compromete mucho con el curso, tanto que saca de su tiempo para dar clases extras de práctica para el examen. Califica normal.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'b16421459e1e11f0248fc932f54ca75cafe78830941b7b28b10728625e71f880'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Se toma todo el tiempo necesario en consulta hasta que uno entienda'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-06T00:00:00+00:00'::TIMESTAMPTZ, '45b6be24eb8ad2f6bba68fe79e3544f2088d9a356f5307b4a3ebd4b7e9f7747b'::TEXT, ARRAY[3057]::BIGINT[]),
    (398::BIGINT, 'El es muy buen profe, explica muy bien y hace muchos ejemplos, pero el curso es bien duro, hay que dedicarle tiempo desde el principio y practicar bastante. Es estricto con las calificaciones'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-31T00:00:00+00:00'::TIMESTAMPTZ, '8554df17063a1d2454065ca1b303f040281710d19501775c0e9e8bdb1327b74f'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Exc Prof, domina la materia y se preocupa por darle al estudiante las herramientas para aprender bien, califica lo más justo posible (no te da más ni menos de lo que mereces), pero tarda en entregar los exámenes justo por ese motivo, los revisa con detalle.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-09-02T00:00:00+00:00'::TIMESTAMPTZ, '8e3cc9cd32d4975da64ea7cca2f9281607222b936dd7271374a4e51805788d82'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Excelente en consulta, explica muy bien y muestra cosas como programas en MATLAB para uno visualizar qué es lo que está enseñando. Llega a ser molesto cuando se empieza a quejar de los que no llegan a clase.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '327ae5ad9d7fc5963136067d29b60a553c754fb10cefe45390b1bc17cb50fbdb'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Devuelve los exámenes muy tarde'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '559c773f402c0d32efab704a1e349cbfa476e0f387b1b69f5e4f655e06434d4b'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'Muy buen profe, hace bastantes ejemplos y explica muy claro, se le nota que domina los temas y que sabe bastante. Califica duro y no regala nada pero es proporcional a lo que enseña. Totalmente recomendado????????????'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'f9a6648cddf278d07a50e1e962a9c7679ea1649b145ebf648305161d1a3a2218'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Hace muchos ejercicios en clase, lo cual hace que la materia quede más clara. De los mejores profes de electrónica, se nota el interés por el estudiante'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '1b23bfcb68d9a2849137482fc8fee77f993645607b377173a08f55779cc9cc6f'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Explica muy bien, hace ejercicios de todo tipo y atiende dudas'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, '6bb0e9fb8f4fa25c72d385daf9c7ebbcffbf7ae7c0f1184e221a24d74b732e17'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Explica muy claro, da muchos ejemplos, atiende dudas, presenta buen manejo del tema y se preocupa por el aprendizaje del estudiante. Asistencia importante. Es estricto, no regala nada y califica fuerte. Para este curso, la mejor opción.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'aa7487c032d8dd31fe98a70a3eeb45813448f9c13e68f4057e5284156979b60d'::TEXT, ARRAY[1296]::BIGINT[]),
    (398::BIGINT, 'El profe es bastante claro a la hora de explicar, la verdad maneja muy bien la materia y a la hora de dar ejemplos comienza desde lo mas basico hasta lo mas complicado. El ambiente en el aula es agradable y es atento a consultas, la verdad si tiene la oportunidad no lo dude. Se aprende bastante.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-23T00:00:00+00:00'::TIMESTAMPTZ, 'fe2e6b35d6fa8ac618059d021c8587ba0c57facb90722a78decea6889652d65b'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Excelente profesor, el curso en sí es rudo, pero el trata de poner muchos ejemplos y tareas para que uno aprenda. Es bastante claro a la hora de explicar. Le hace competencia Arriola.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2018-05-18T00:00:00+00:00'::TIMESTAMPTZ, 'c01ca5702edf6e84fe95ef04ee6c46997366c446e75e281713820375ee4fe5ff'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Se preocupa por que el estudiante aprenda'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'e7b3c46ab4da9cda7b2027e3bea4bafc11fd3cd675c980f1b5b46171c3ab7909'::TEXT, ARRAY[1386, 1297, 3556]::BIGINT[]),
    (398::BIGINT, 'Explica bastante bien, hace bastantes ejemplos, algunos duros otros que se hacen solos pero es para que todos entiendan, en consulta ayuda mucho. Revisa sin piedad de nada, pero ayuda en cada examen. Clases intensas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-22T00:00:00+00:00'::TIMESTAMPTZ, '224ce43a2cab4c0a5591d58c5c82bca1d30d6c3d0e7c713113a78571912b2c90'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Hace muchos ejemplos en clase. La mayoria de la materia y los ejemplos son del Sadiku, pero aveces hace ejemplos adicionales que ayudan para el examen, ademas da tips adicionales que no estan en el libro. Califica bien.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-09T00:00:00+00:00'::TIMESTAMPTZ, '3eaf3e0e3ba93894b7d63f3b3267edf3f0ef155127056fc279aaf8deab9fc66c'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Es buen profe explica bien y ayuda en consulta. Califica justo y no hace curva, en general si quiere aprender y pasar sin que le regalen nada lo recomiendo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '68fb78820b5a6b9751d5631452b84b2b70f66448dd7fe9598324df1d309e531a'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'El curso es duro y con él se aprende bien. Si de verdad quiere aprender llevelo con él. Califica justo y muy atento para aclarar dudas. Ayuda bastante en consulta y es buena persona.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '647395457c654816bfa6f13e6f5d4bb37efd9e0da0d244b5dd2cdd4ba760d34a'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Excelente profesor, maneja muy bien la materia. Califica un poco duro, super atento para aclarar dudas y dispuesto a ayudar'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'd3c5e0188e82df7f21adfd467bac1b1a4d79a28ccf40e689179984dd58ab7b29'::TEXT, ARRAY[1386, 1297, 3556]::BIGINT[]),
    (398::BIGINT, 'CA es un curso con mucha materia y muy importante en la carrera, así que si de verdad quiere aprender, lleve lo con él, eso sí, preparese para la cromada que le va a meter, CALIFICA DURO. Siempre pregunte y si va a consulta, ayuda...'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-12T00:00:00+00:00'::TIMESTAMPTZ, '9f4f0da79db5dacece91940d8f9ef53f2926e1371332073ebeb80dd34a83cf71'::TEXT, ARRAY[1262]::BIGINT[]),
    (398::BIGINT, 'Se basa en presentaciones muy tediosas. Es bueno explicando, pero no tiene piedad al calificar. En sí, es un profe regular.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-06T00:00:00+00:00'::TIMESTAMPTZ, '80df7703fab6d62942f6b74940252937660036228cee2897b6d04239b73fbb50'::TEXT, ARRAY[1386, 1297, 3556]::BIGINT[]),
    (398::BIGINT, 'Que va, barboza es un profesor teórico no sirve, mejor ver los videos de pablo son más productivos que sus clases. Es triste por que califica muy duro. Y como siempre solo pasa el 5% del grupo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-10-19T00:00:00+00:00'::TIMESTAMPTZ, '27accde568e4bea68843ae0697575c5dd625ecf53db9e2ae92f55ca9272b713c'::TEXT, ARRAY[1386, 1297, 3556]::BIGINT[]),
    (398::BIGINT, 'Es un profesor joven, le falta experiencia. En mi clase pasaron muy pocos. Clases muy largas, explica muy bien, pero califica DURO.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'b5aed1c3516c4f341e005a9cb1fb7600060d0b330af81eb6c97a27f7b84861db'::TEXT, ARRAY[3057]::BIGINT[]),
    (398::BIGINT, 'El profe sabe, pero se enfoca demasiado en aspectos teóricos, no sabe dar la clase, llega a leer presentaciones de más de 100 diapositivas sacadas directamente del libro del curso y las explicaciones son sacadas de videos de youtube. Si se va a consulta ayuda. Califica muy duro.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'b1f0a4e2c4ed2793685d5e2ae5ec92bcb95fdc95671b4aeca7d7c3de2abef00a'::TEXT, ARRAY[1386, 1297, 3556]::BIGINT[]),
    (398::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '47fab93f882ed497b643eff20dd11710c61311984d161eb0d35531e7a434cea2'::TEXT, ARRAY[3057]::BIGINT[]),
    (398::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'e3c635299771a4bc100d946a8051df19fee5adbc77561b9a3c2dfec7c3bd79e3'::TEXT, ARRAY[3057]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
